def _startup_banner_line(
    repo_name: str,
    sha: str,
    diff_count: int | None,
    mode: str,
    backend_name: str,
    timeout_s: int | None,
) -> str:
    """One stderr line stating what review is about to run.

    Prints repo@sha, diff size, mode, backend, and the effective LLM
    timeout with its override variable. A wrong cwd, wrong target, or
    surprise timeout budget (FORGE_LLM_TIMEOUT_S) is visible in the
    first seconds instead of after the first deadline.
    """
    if sha:
        target = "%s @ %s" % (repo_name, sha)
    else:
        target = repo_name
    if diff_count is None:
        diff_str = "n/a"
    else:
        diff_str = "%d file%s" % (
            diff_count, "" if diff_count == 1 else "s"
        )
    if timeout_s is not None:
        timeout_str = "%ds" % timeout_s
    else:
        timeout_str = "n/a"
    return (
        "code-forge: reviewing %s (diff: %s); mode: %s; backend: %s; "
        "LLM timeout: %s (override: FORGE_LLM_TIMEOUT_S)"
        % (target, diff_str, mode, backend_name, timeout_str)
    )

